cat > ParseBinlog.cs << 'CEOF'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

        // Collect all errors
        var errors = new System.Collections.Generic.List<(string project, string code, string message, string file, int line)>();
        build.VisitAllChildren<Error>(e => {
            string project = "";
            var node = (BaseNode)e;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            errors.Add((project, e.Code ?? "", e.ToString(), e.File ?? "", e.LineNumber));
        });

        // Collect all warnings
        var warnings = new System.Collections.Generic.List<(string project, string code, string message)>();
        build.VisitAllChildren<Warning>(w => {
            string project = "";
            var node = (BaseNode)w;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            warnings.Add((project, w.Code ?? "", w.ToString()));
        });

        Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
        foreach (var g in errors.GroupBy(e => e.project))
        {
            Console.WriteLine($"\n--- Project: {g.Key} ---");
            foreach (var e in g)
                Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
        }

        if (warnings.Any())
        {
            Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
            foreach (var g in warnings.GroupBy(w => w.project))
            {
                Console.WriteLine($"\n--- Project: {g.Key} ---");
                foreach (var w in g)
                    Console.WriteLine($"  [{w.code}] {w.message}");
            }
        }

        // Show project dependency info
        Console.WriteLine("\n=== PROJECT BUILD ORDER & RESULTS ===");
        build.VisitAllChildren<Project>(p => {
            var hasErrors = false;
            p.VisitAllChildren<Error>(e => hasErrors = true);
            if (hasErrors || !p.Succeeded)
                Console.WriteLine($"  {(p.Succeeded ? "OK" : "FAIL")} {p.Name} [{p.TargetFramework}]");
        });
    }
}
