using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Show all projects
        Console.WriteLine("=== ALL PROJECTS ===");
        build.VisitAllChildren<Project>(p => {
            Console.WriteLine($"  {p.Name} [{p.TargetFramework}]");
        });

        // Show source files embedded in binlog
        Console.WriteLine("\n=== EMBEDDED FILES ===");
        try {
            var reader = new BinLogReader();
            foreach (var record in reader.ReadRecords(args[0]))
            {
                var eventArgs = record.Args;
                if (eventArgs is Microsoft.Build.Framework.BuildErrorEventArgs err)
                {
                    Console.WriteLine($"Error in {err.ProjectFile}: {err.File}({err.LineNumber}): {err.Code}: {err.Message}");
                }
            }
        } catch (Exception ex) {
            Console.WriteLine($"Error reading: {ex.Message}");
        }

        // Try to get source files from the binlog
        Console.WriteLine("\n=== SOURCE FILE CONTENTS FROM BINLOG ===");
        var archiveReader = new Microsoft.Build.Logging.StructuredLogger.BinLogReader();
        var sourceFiles = BinaryLog.ReadBuild(args[0]);
        sourceFiles.VisitAllChildren<SourceFile>(sf => {
            Console.WriteLine($"\n--- FILE: {sf.Name} ---");
        });

        // Look at items/references
        Console.WriteLine("\n=== ITEMS/REFERENCES ===");
        build.VisitAllChildren<Item>(item => {
            if (item.Name?.Contains("Reference") == true || item.Name?.Contains("PackageReference") == true)
            {
                string project = "";
                var node = (BaseNode)item;
                while (node.Parent != null) {
                    if (node is Project p) { project = p.Name; break; }
                    node = (BaseNode)node.Parent;
                }
                if (project.Contains("Services"))
                    Console.WriteLine($"  [{project}] {item.Name}: {item.Text}");
            }
        });
    }
}
