using System;
using System.Linq;
using System.Reflection;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        Console.WriteLine("=== ALL PROJECTS ===");
        build.VisitAllChildren<Project>(p => {
            Console.WriteLine($"  {p.Name} [{p.TargetFramework}]");
        });

        Console.WriteLine("\n=== EMBEDDED SOURCE FILES ===");
        build.VisitAllChildren<SourceFile>(sf => {
            Console.WriteLine($"\n--- FILE: {sf.Name} ---");
            // Dump all properties
            foreach (var prop in sf.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                try { Console.WriteLine($"  {prop.Name} = {prop.GetValue(sf)}"); } catch {}
            }
        });

        // Try SourceFilesArchive
        Console.WriteLine("\n=== TRYING ARCHIVE READER ===");
        try {
            var files = BinaryLog.ReadSourceFiles(args[0]);
            foreach (var kvp in files)
            {
                Console.WriteLine($"\n--- ARCHIVED FILE: {kvp.Key} ---");
                Console.WriteLine(kvp.Value);
            }
        } catch (Exception ex) {
            Console.WriteLine($"ReadSourceFiles error: {ex.Message}");
        }

        Console.WriteLine("\n=== PACKAGE REFERENCES (Services.csproj) ===");
        build.VisitAllChildren<Item>(item => {
            string project = "";
            var node = (BaseNode)item;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            if (project.Contains("Services") && (item.Name?.Contains("Reference") == true || item.Name?.Contains("Package") == true))
                Console.WriteLine($"  {item.Name}: {item.Text}");
        });
    }
}
