using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Show all projects uniquely
        var projects = new HashSet<string>();
        build.VisitAllChildren<Project>(p => projects.Add(p.Name));
        Console.WriteLine("=== PROJECTS ===");
        foreach (var p in projects) Console.WriteLine($"  {p}");

        // All errors
        Console.WriteLine("\n=== ALL ERRORS ===");
        build.VisitAllChildren<Error>(e => {
            string project = "";
            var node = (BaseNode)e;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            Console.WriteLine($"  [{project}] {e.Code}: {e}");
        });

        // All items for Services project
        Console.WriteLine("\n=== ALL ITEM GROUPS (Services.csproj) ===");
        var seen = new HashSet<string>();
        build.VisitAllChildren<Folder>(f => {
            string project = "";
            var node = (BaseNode)f;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            if (project == "Services.csproj" && f.Name == "Items")
            {
                foreach (var child in f.Children.OfType<NamedNode>())
                {
                    var key = $"{child.Name}";
                    if (seen.Add(key))
                        Console.WriteLine($"  ItemGroup: {child.Name} ({child.Children.Count} items)");
                }
            }
        });

        // Look for PackageReference specifically
        Console.WriteLine("\n=== NAMED NODES IN Services.csproj ===");
        var seenNodes = new HashSet<string>();
        build.VisitAllChildren<NamedNode>(n => {
            string project = "";
            var node = (BaseNode)n;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            if (project == "Services.csproj" && n.Name?.Contains("Package") == true)
            {
                var key = $"{n.GetType().Name}: {n.Name} = {n}";
                if (seenNodes.Add(key))
                    Console.WriteLine($"  {key}");
            }
        });

        // Properties
        Console.WriteLine("\n=== KEY PROPERTIES (Services.csproj) ===");
        var seenProps = new HashSet<string>();
        build.VisitAllChildren<Property>(prop => {
            string project = "";
            var node = (BaseNode)prop;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            if (project == "Services.csproj" && (prop.Name == "ProjectFile" || prop.Name == "TargetFramework" || prop.Name?.Contains("Package") == true))
            {
                var key = $"{prop.Name} = {prop}";
                if (seenProps.Add(key))
                    Console.WriteLine($"  {key}");
            }
        });

        // Get all messages about restore/packages
        Console.WriteLine("\n=== RESTORE/PACKAGE MESSAGES ===");
        build.VisitAllChildren<Message>(m => {
            if (m.Text?.Contains("Newtonsoft") == true || m.Text?.Contains("PackageReference") == true)
                Console.WriteLine($"  {m.Text}");
        });

        // Get embedded source files from binlog using BinLogReader
        Console.WriteLine("\n=== SOURCE FILES FROM RECORDS ===");
        var reader = new BinLogReader();
        var embeddedFiles = new Dictionary<string, string>();
        foreach (var record in reader.ReadRecords(args[0]))
        {
            if (record.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg)
            {
                if (msg.Message?.Contains(".csproj") == true && msg.Message?.Contains("Package") == true)
                    Console.WriteLine($"  MSG: {msg.Message}");
            }
        }

        // Try the archive
        Console.WriteLine("\n=== ARCHIVE FILES ===");
        try {
            var archiveFiles = BinaryLog.ReadBuild(args[0]);
            archiveFiles.VisitAllChildren<SourceFile>(sf => {
                Console.WriteLine($"  SourceFile: {sf.Name}");
            });
        } catch {}

        // Try to find the actual csproj content in the binlog
        Console.WriteLine("\n=== LOOKING FOR CSPROJ CONTENT ===");
        var reader2 = new BinLogReader();
        foreach (var record in reader2.ReadRecords(args[0]))
        {
            var ea = record.Args;
            // Check for EmbeddedFile
            var type = ea.GetType();
            if (type.Name.Contains("Evaluation") || type.Name.Contains("Project"))
            {
                var props = type.GetProperties();
                foreach (var prop in props)
                {
                    if (prop.Name == "ProjectFile" || prop.Name == "ImportedProjectFile")
                    {
                        try {
                            var val = prop.GetValue(ea)?.ToString();
                            if (val?.Contains("Services") == true)
                                Console.WriteLine($"  {type.Name}.{prop.Name} = {val}");
                        } catch {}
                    }
                }
            }
        }
    }
}
