using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Dump full tree for Services.csproj - just first level children
        Console.WriteLine("=== SERVICES.CSPROJ TREE (depth 3) ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name != "Services.csproj") return;
            PrintTree(p, 0, 4);
        });
    }

    static bool printed = false;
    static void PrintTree(BaseNode node, int depth, int maxDepth)
    {
        if (printed) return;
        if (depth >= maxDepth) return;
        var indent = new string(' ', depth * 2);
        var name = node is NamedNode nn ? nn.Name : node.GetType().Name;
        var text = node.ToString();
        if (text.Length > 200) text = text.Substring(0, 200) + "...";
        Console.WriteLine($"{indent}{node.GetType().Name}: {text}");
        if (node is TreeNode tn)
        {
            foreach (var child in tn.Children)
            {
                if (child is BaseNode bn)
                    PrintTree(bn, depth + 1, maxDepth);
            }
        }
    }
}
