using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static bool printed = false;
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Find the build target invocation with errors
        Console.WriteLine("=== SERVICES.CSPROJ BUILD TARGET TREE ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name != "Services.csproj") return;
            // Check if this project instance has errors
