using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Dump ALL errors with full details
        Console.WriteLine("=== ALL ERRORS ===");
        build.VisitAllChildren<Error>(e => {
            Console.WriteLine($"  Code: {e.Code}");
            Console.WriteLine($"  File: {e.File}");
            Console.WriteLine($"  Line: {e.LineNumber}");
            Console.WriteLine($"  Message: {e}");
            Console.WriteLine();
        });

        // Find project dependencies  
        Console.WriteLine("=== PROJECT REFERENCES ===");
        build.VisitAllChildren<Item>(item => {
            if (item.Text?.EndsWith(".csproj") == true)
            {
                string project = "";
                var node = (BaseNode)item;
                while (node.Parent != null) {
                    if (node is Project p) { project = p.Name; break; }
                    node = (BaseNode)node.Parent;
                }
                string parentName = "";
                var parent = (BaseNode)item;
                while (parent.Parent != null) {
                    if (parent is AddItem ai) { parentName = ai.Name; break; }
                    if (parent is Folder f) { parentName = f.Name; break; }
                    parent = (BaseNode)parent.Parent;
                }
                if (parentName.Contains("Reference") || parentName.Contains("Restore"))
                    Console.WriteLine($"  [{project}] {parentName}: {item.Text}");
            }
        });

        // Check all resolved assemblies for Services
        Console.WriteLine("\n=== RESOLVED ASSEMBLIES (Services.csproj) ===");
        var seen = new HashSet<string>();
        build.VisitAllChildren<Item>(item => {
            string project = "";
            var node = (BaseNode)item;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            string parentName = "";
            var parent = (BaseNode)item;
            while (parent.Parent != null) {
                if (parent is AddItem ai) { parentName = ai.Name; break; }
                parent = (BaseNode)parent.Parent;
            }
            if (project == "Services.csproj" && parentName.Contains("Reference") && seen.Add($"{parentName}:{item.Text}"))
                Console.WriteLine($"  {parentName}: {item.Text}");
        });

        // Find the "Compile" items for Services
        Console.WriteLine("\n=== COMPILE ITEMS (Services.csproj) ===");
        var seenCompile = new HashSet<string>();
        build.VisitAllChildren<Item>(item => {
            string project = "";
            var node = (BaseNode)item;
            while (node.Parent != null) {
                if (node is Project p) { project = p.Name; break; }
                node = (BaseNode)node.Parent;
            }
            string parentName = "";
            var parent = (BaseNode)item;
            while (parent.Parent != null) {
                if (parent is AddItem ai) { parentName = ai.Name; break; }
                parent = (BaseNode)parent.Parent;
            }
            if (project == "Services.csproj" && parentName == "Compile" && seenCompile.Add(item.Text))
                Console.WriteLine($"  {item.Text}");
        });

        // Check if Api depends on Services
        Console.WriteLine("\n=== API.CSPROJ DEPENDENCIES ===");
        build.VisitAllChildren<Item>(item => {
            if (item.Text?.Contains("Services") == true)
            {
                string project = "";
                var node = (BaseNode)item;
                while (node.Parent != null) {
                    if (node is Project p) { project = p.Name; break; }
                    node = (BaseNode)node.Parent;
                }
                if (project == "Api.csproj")
                {
                    string parentName = "";
                    var parent = (BaseNode)item;
                    while (parent.Parent != null) {
                        if (parent is AddItem ai) { parentName = ai.Name; break; }
                        parent = (BaseNode)parent.Parent;
                    }
                    if (seen.Add($"api:{parentName}:{item.Text}"))
                        Console.WriteLine($"  {parentName}: {item.Text}");
                }
            }
        });
    }
}
