using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // ALL errors
        Console.WriteLine("=== ALL ERRORS ===");
        build.VisitAllChildren<Error>(e => {
            Console.WriteLine($"  {e.Code}: {e}");
        });

        // ALL warnings  
        Console.WriteLine("\n=== ALL WARNINGS ===");
        build.VisitAllChildren<Warning>(w => {
            Console.WriteLine($"  {w.Code}: {w}");
        });

        // Find unique item names for the Services project with errors
        Console.WriteLine("\n=== UNIQUE ADD-ITEM NAMES (Services build with errors) ===");
        var seen = new HashSet<string>();
        bool found = false;
        build.VisitAllChildren<Project>(p => {
            if (p.Name != "Services.csproj" || found) return;
            bool hasErrors = false;
            p.VisitAllChildren<Error>(e => hasErrors = true);
            if (!hasErrors) return;
            found = true;

            p.VisitAllChildren<AddItem>(ai => {
                if (seen.Add(ai.Name))
                    Console.WriteLine($"  {ai.Name}");
            });
        });

        // Check if any project has Newtonsoft in its resolved refs
        Console.WriteLine("\n=== NEWTONSOFT IN ANY PROJECT ===");
        build.VisitAllChildren<Item>(item => {
            if (item.Text?.Contains("Newtonsoft") == true)
            {
                string project = "";
                var node = (BaseNode)item;
                while (node.Parent != null) {
                    if (node is Project p) { project = p.Name; break; }
                    node = (BaseNode)node.Parent;
                }
                Console.WriteLine($"  [{project}] {item.Text}");
            }
        });

        // Check evaluation messages for Newtonsoft
